def train_flops(n_params, n_tokens):
    return 6 * n_params * n_tokens          # 순전파 2ND + 역전파 4ND

def gpu_days(flops, peak=989e12, mfu=0.4, n_gpu=1):
    return flops / (peak * mfu * n_gpu) / 86400

for name, N, D in [("GPT-3", 175e9, 300e9), ("Llama 3 405B", 405e9, 15e12)]:
    C = train_flops(N, D)
    print(f"{name:13s} C = {C:.2e} FLOPs | H100 1장 {gpu_days(C):,.0f}일"
          f" | 1024장 {gpu_days(C, n_gpu=1024):,.1f}일")
